contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an address 'caller' to simulate different msg.sender via call() on c from this contract.
    // To send Ether to c we pass `amount` and ensure this contract has enough balance.
    function run(address caller, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Read balance before
        uint256 beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBal = address(c).balance;

        // Perform Deposit by calling c.Deposit and forwarding value `amount`.
        // We capture whether it reverted.
        bool reverted = false;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values irrespective of revert
        uint256 afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBal = address(c).balance;

        // If the call did not revert, then the caller's recorded balance must have increased by exactly amount
        // and the contract's Ether balance must have increased by exactly amount.
        assert(reverted || (afterBal == beforeBal + amount && afterContractBal == beforeContractBal + amount));
    }

    // Allow this contract to receive Ether so it can forward to c
    receive() external payable {}
}

